-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

create table public.news_reads (
  user_id uuid default auth.uid() not null,
  seen_until timestamp with time zone not null,
  updated_at timestamp with time zone default now() not null,
  constraint news_reads_pkey PRIMARY KEY (user_id),
  constraint news_reads_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE
);

alter table public.news_reads enable row level security;

create policy "read own news reads" on public.news_reads
  as permissive
  for select
  to authenticated
  using (((user_id = ( SELECT auth.uid() AS uid)) AND ( SELECT public.is_allowed_user() AS is_allowed_user)));

grant select on table public.news_reads to authenticated;
grant delete, insert, maintain, references, select, trigger, truncate, update on table public.news_reads to service_role;
